package com.example.commerce.wishlist; import java.util.*; import javax.validation.Valid; import javax.validation.constraints.NotNull; import com.example.commerce.common.CommerceException; import com.example.commerce.config.SecurityConfig; import com.example.commerce.product.*; import com.example.commerce.user.User; import lombok.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/wishlist") @PreAuthorize("hasRole('CUSTOMER')") @Transactional public class WishlistController {private final WishlistRepository repo;private final ProductRepository products;public WishlistController(WishlistRepository r,ProductRepository p){repo=r;products=p;}@Getter @Setter public static class Request{@NotNull Long productId;}@Getter @AllArgsConstructor public static class Response{long productId;String name;}@GetMapping @Transactional(readOnly=true) List<Response> get(){List<Response> out=new ArrayList<>();repo.findByUserId(SecurityConfig.currentUser().getId()).forEach(x->out.add(new Response(x.getProduct().getId(),x.getProduct().getName())));return out;}@PostMapping("/items") ResponseEntity<Response> add(@Valid @RequestBody Request r){User u=SecurityConfig.currentUser();if(repo.findByUserIdAndProductId(u.getId(),r.getProductId()).isPresent())throw new CommerceException(HttpStatus.CONFLICT,"Product is already wishlisted");Product p=products.findById(r.getProductId()).filter(Product::isActive).orElseThrow(()->new CommerceException(HttpStatus.NOT_FOUND,"Product not found"));WishlistItem i=new WishlistItem();i.setUser(u);i.setProduct(p);repo.save(i);return ResponseEntity.status(201).body(new Response(p.getId(),p.getName()));}@DeleteMapping("/items/{productId}") ResponseEntity<Void> remove(@PathVariable Long productId){WishlistItem i=repo.findByUserIdAndProductId(SecurityConfig.currentUser().getId(),productId).orElseThrow(()->new CommerceException(HttpStatus.NOT_FOUND,"Wishlist item not found"));repo.delete(i);return ResponseEntity.noContent().build();}}
